    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xDDC901869D1F3DC1ULL + 0xA80FD794C99A8243ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xB19BBD6123599641ULL + 0xAEFB0527837CBCD5ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0x85F4590D21222F4BULL + 0xC7B3C53AAD6F2319ULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xF7892BFDAB2134E1ULL + 0x8C7023A23F0FBE3CULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xFC12AD947BCB631DULL + 0x9154564D070E2D83ULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0xA5A02E719035636FULL + 0xE2B0F59DFDA9ED0DULL);
    const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0x8F71FBEDEF3DEAE9ULL + 0xBF02F35356E72F0CULL);
    const std::uint64_t aNonceWordH = TwistMix64::DiffuseC(pNonce * 0x88C5D79180CB173FULL + 0xAA339A52CF48FD01ULL);
    const std::uint64_t aNonceWordI = TwistMix64::DiffuseC(pNonce * 0xAF6C8EB5C6F4D8DFULL + 0xF5137A9263C1BB19ULL);
    const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0xA6DF9D2DF7B71DDDULL + 0xB2090FFC75B9E562ULL);
    const std::uint64_t aNonceWordK = TwistMix64::DiffuseC(pNonce * 0xD001B584F75880C5ULL + 0xA0461C53A6B0DD18ULL);
    const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0xD62E6B0A4E2935D3ULL + 0xCFE7C98290890CF4ULL);
    const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0xD945969C76BC0123ULL + 0xFB057148D21CAF99ULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseB(pNonce * 0xE12A274A30424211ULL + 0xACD5FFB99A248D78ULL);
    const std::uint64_t aNonceWordO = TwistMix64::DiffuseC(pNonce * 0xF1BAD085399CEC37ULL + 0xAFC1DD994075162AULL);
    const std::uint64_t aNonceWordP = TwistMix64::DiffuseA(pNonce * 0x9A3DA00CEE3D71BFULL + 0xDDDBFB8B71C8E74BULL);
