            aOrbiterI = (((aWandererA + RotL64(aIngress, 41U)) + RotL64(aCarry, 57U)) + 0x915E9F20264FD453ULL) + aNonceWordN;
            aOrbiterJ = ((aWandererH + RotL64(aScatter, 24U)) + 0x87436C948E375DCDULL) + aOASaltA[(((511U - aIndex) + 142U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aPrevious, 51U)) + 0xE8EB6D6066C2EF59ULL) + aNonceWordK;
            aOrbiterH = ((aWandererK + RotL64(aCross, 37U)) + 0x39774E3144E6494FULL) + aOASaltD[((aIndex + 113U)) & S_SALT1];
            aOrbiterE = (((aWandererD + RotL64(aIngress, 5U)) + RotL64(aCarry, 37U)) + 0x324AE8F29502DD46ULL) + aNonceWordL;
            aOrbiterC = ((aWandererB + RotL64(aScatter, 54U)) + 0x8E39DE08485A73D9ULL) + aOASaltC[((aIndex + 331U)) & S_SALT1];
            aOrbiterG = (aWandererI + RotL64(aPrevious, 29U)) + 0xB1A3640C26631779ULL;
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0xFDC34A63FB875695ULL) + aNonceWordA;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0x2D039430EC06A74FULL;
            aOrbiterK = RotL64((aOrbiterK * 0x87CF486D3102AAF9ULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xF1A4DAA5AD74AA09ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x9740E194C35A0DA3ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xCDCADE6748BDB9B9ULL), 19U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x934C1D43579B4B83ULL;
