            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x894084F939BA8814ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0xFB7EA9C85BFBB1D5ULL;
