            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x05FCD96FA67EB7CCULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x14436AB3FB5E0F11ULL;
