            aWandererB = aWandererB + ((((RotL64(aPrevious, 3U) + aOrbiterE) + RotL64(aOrbiterG, 43U)) + RotL64(aCarry, 35U)) + aWUSaltD[((aIndex + 356U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aCross, 39U) + aOrbiterC) + RotL64(aOrbiterJ, 3U));
