            aOrbiterI = (((aWandererI + RotL64(aScatter, 5U)) + RotL64(aCarry, 53U)) + 0xD1E2CE8663D1B70AULL) + aOASaltC[((aIndex + 277U)) & S_SALT1];
            aOrbiterH = (aWandererG + RotL64(aPrevious, 29U)) + 0x9D55F34473716D67ULL;
            aOrbiterA = ((aWandererD + RotL64(aCross, 3U)) + 0xB3C4DB05A9F74234ULL) + aOASaltE[((aIndex + 211U)) & S_SALT1];
            aOrbiterK = (((aWandererA + RotL64(aIngress, 26U)) + RotL64(aCarry, 13U)) + 0x4C1833EFD6E0CD8BULL) + aOASaltG[((aIndex + 509U)) & S_SALT1];
            aOrbiterE = (aWandererF + RotL64(aScatter, 53U)) + 0x15E0D7967942D77CULL;
            aOrbiterB = (aWandererK + RotL64(aPrevious, 35U)) + 0xDD712D890D34AC97ULL;
            aOrbiterG = (aWandererH + RotL64(aCross, 57U)) + 0xE85A95C8853BDFB4ULL;
            aOrbiterJ = ((aWandererC + RotL64(aIngress, 23U)) + RotL64(aCarry, 57U)) + 0xA042E971846C2119ULL;
            aOrbiterF = ((aWandererJ + RotL64(aScatter, 19U)) + 0xF9DFA53CD8A88FD4ULL) + aOASaltD[(((511U - aIndex) + 504U)) & S_SALT1];
