            aWandererE = aWandererE ^ ((RotL64(aCross, 43U) + RotL64(aOrbiterB, 29U)) + aOrbiterI);
            aWandererC = aWandererC + (((RotL64(aIngress, 11U) + RotL64(aOrbiterH, 39U)) + aOrbiterF) + aWUSaltG[((aIndex + 11U)) & S_SALT1]);
