            aWandererA = aWandererA + ((((RotL64(aPrevious, 41U) + aOrbiterF) + RotL64(aOrbiterG, 29U)) + RotL64(aCarry, 23U)) + aWUSaltD[(((511U - aIndex) + 64U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aCross, 27U) + aOrbiterB) + RotL64(aOrbiterE, 39U));
