            aOrbiterA = ((aWandererI + RotL64(aScatter, 29U)) + RotL64(aCarry, 47U)) + 0xAC36D342AA81D2ABULL;
            aOrbiterI = (aWandererJ + RotL64(aPrevious, 26U)) + 0xF8199DA37AA2733EULL;
            aOrbiterD = ((aWandererE + RotL64(aCross, 37U)) + 0x722EC548CBCC0D09ULL) + aOASaltG[(((511U - aIndex) + 449U)) & S_SALT1];
            aOrbiterC = (aWandererF + RotL64(aIngress, 41U)) + 0x4D551D76AB8E58BCULL;
            aOrbiterH = (((aWandererA + RotL64(aScatter, 3U)) + RotL64(aCarry, 3U)) + 0x3EBAEAB5174075DAULL) + aOASaltD[((aIndex + 481U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aPrevious, 35U)) + 0x750C6425FD78DCC7ULL;
