            aOrbiterE = ((aWandererH + RotL64(aScatter, 5U)) + RotL64(aCarry, 35U)) + 0x6F6C3D2C44F8F99DULL;
            aOrbiterF = (aWandererK + RotL64(aPrevious, 23U)) + 0x953B60F95C0627EDULL;
            aOrbiterG = ((aWandererD + RotL64(aCross, 19U)) + 0xA4B1AA9C51A623F0ULL) + aOASaltH[((aIndex + 184U)) & S_SALT1];
