            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x2D50F752C941E8B7ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xAAE57C88309A7529ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x1F57A11F099130F3ULL), 43U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0xD4D52F7F59FC179CULL) + aOUSaltB[(((511U - aIndex) + 163U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x4A2E148F5140A7D7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x35378B81718E9A93ULL), 53U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xA48CE9056433D311ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x140497539BF350F2ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xED1013F40D9D2619ULL), 29U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x0226DB06D0170B42ULL) + aOUSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0xE4112F8AE31392CBULL;
