            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x68D9253E190777F6ULL) + aOUSaltG[((aIndex + 383U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x3A856D30C5C9F3A2ULL;
