            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0x1A1041DACF56B71AULL) + aOUSaltA[(((511U - aIndex) + 390U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x50BC7C3FA14F80EEULL;
